from pathlib import Path
import json
import re
from datetime import datetime

def verify(workspace_path, external_services_path=None):
    try:
        slack_path = None
        if external_services_path is not None:
            candidate = Path(external_services_path) / 'slack_data.json'
            if candidate.exists():
                slack_path = candidate
        if slack_path is None:
            candidates = list(Path(workspace_path).glob('*slack*.json'))
            if candidates:
                slack_path = candidates[0]
        if slack_path is None:
            return {'pass': False, 'score': 0.0, 'feedback': 'No slack_data.json found'}

        with open(slack_path, 'r') as f:
            data = json.load(f)

        cutoff_ts = datetime(2026, 4, 14).timestamp()
        messages_dict = data.get('messages', {})
        channels = data.get('channels', {})
        users = data.get('users', {})

        def _resolve_mentions(text):
            def rep(m):
                u = users.get(m.group(1), {})
                return f"{u.get('name', '')} {u.get('real_name', '')}"
            return re.sub(r'<@(U\w+)>', rep, text)

        target_keys = set()
        for cid, cinfo in channels.items():
            cname = cinfo.get('name', '').lower()
            if 'acct' in cname and 'deal' in cname and 'post' in cname:
                target_keys.add(cid)
                target_keys.add(cname)
        for key in messages_dict:
            key_lower = key.lower()
            if 'acct' in key_lower and 'deal' in key_lower and 'post' in key_lower:
                target_keys.add(key)

        if not target_keys:
            return {'pass': False, 'score': 0.0, 'feedback': 'Cannot identify acct-deal-posting channel'}

        for channel_key in target_keys:
            msgs = messages_dict.get(channel_key, [])
            for msg in msgs:
                if not isinstance(msg, dict):
                    continue
                ts = float(msg.get('ts', 0))
                if ts < cutoff_ts:
                    continue
                text = _resolve_mentions(str(msg.get('text', ''))).lower()
                has_deal = '4821' in text
                has_marcus = 'marcus' in text or 'marcus.hale' in text
                has_gross = '5640' in text.replace(',', '').replace(' ', '') or '5,640' in text
                if has_deal and has_marcus and has_gross:
                    return {'pass': True, 'score': 1.0,
                            'feedback': f'Found high-gross confirmation notice referencing 4821, Marcus, and gross $5,640 in acct-deal-posting (key={channel_key})'}

        return {'pass': False, 'score': 0.0,
                'feedback': 'No high-gross confirmation notice found referencing 4821, Marcus Hale, and total gross 5640 in acct-deal-posting channel on/after April 14 2026'}
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Error: {e}'}
